#include <string>
#include <sstream>

class Solution {
private:
    int toSec(const std::string& t) {
        int h, m, s;
        char c1, c2;
        std::stringstream ss(t);
        ss >> h >> c1 >> m >> c2 >> s;
        return h * 3600 + m * 60 + s;
    }
public:
    int elapsedSeconds(std::string time1, std::string time2) {
        int s1 = toSec(time1);
        int s2 = toSec(time2);
        return s2 >= s1 ? s2 - s1 : s2 - s1 + 86400;
    }
};

class Solution {
    private int toSec(String t) {
        String[] parts = t.split(":");
        int h = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        int s = Integer.parseInt(parts[2]);
        return h * 3600 + m * 60 + s;
    }

    public int elapsedSeconds(String time1, String time2) {
        int s1 = toSec(time1);
        int s2 = toSec(time2);
        return s2 >= s1 ? s2 - s1 : s2 - s1 + 86400;
    }
}

